// Intended function: expose only choices whose standing/flags are satisfied and return explicit state deltas rather than mutating unrelated systems.
#include "gameplay/DialogueSystem.hpp"
#include <algorithm>
namespace elysium{bool DialogueSystem::add(DialogueNode n){if(!n.nodeId||nodes_.contains(n.nodeId))return false;nodes_[n.nodeId]=std::move(n);return true;}std::optional<DialogueNode>DialogueSystem::node(std::uint64_t id)const{auto i=nodes_.find(id);return i==nodes_.end()?std::nullopt:std::optional<DialogueNode>(i->second);}std::vector<DialogueChoice>DialogueSystem::availableChoices(std::uint64_t id,const DialogueContext&c)const{std::vector<DialogueChoice>o;auto i=nodes_.find(id);if(i==nodes_.end())return o;for(auto&x:i->second.choices)if(c.standing>=x.minStanding&&(c.flags&x.requiredFlags)==x.requiredFlags)o.push_back(x);std::sort(o.begin(),o.end(),[](auto&a,auto&b){return a.choiceId<b.choiceId;});return o;}bool DialogueSystem::applyChoice(DialogueContext&c,const DialogueChoice&x)const{if(c.standing<x.minStanding||(c.flags&x.requiredFlags)!=x.requiredFlags)return false;c.flags|=x.setFlags;c.standing=std::clamp(c.standing+x.standingDelta,-100.f,100.f);return true;}}
